const cmd=`python3 -c 'import csv,gzip,sys
for p in sys.argv[1:]:
 with gzip.open(p,"rt",newline="") as f: rows=list(csv.DictReader(f))
 print(p)
 for label in sorted(set(r["label"] for r in rows)):
  a=sorted(int(r["elapsed"]) for r in rows if r.get("label")==label and r.get("timeStamp") and r.get("elapsed"))
  def pct(q): return a[min(len(a)-1,int((len(a)-1)*q+0.999999))]
  print(label,len(a),pct(.95),pct(.99))
